INSERT INTO public.notes VALUES ('6e83289c-ddb5-46b0-a188-8eb21845eb4c', '29385413-4327-42e7-be9b-fd14b56669ee', 'Confounding compounding', 'The majority of Warren Buffet''s worth came after his 60. Let the money compound to generate higher wealth', NULL, '2026-08-04 14:01:05.549471+00', '2026-08-04 14:01:05.549471+00', 'note');
INSERT INTO public.notes VALUES ('69690703-5bf5-492c-a231-03a4029bf84e', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'Only a thought we’ve lived has any value.', NULL, '2026-07-28 06:08:36.627705+00', '2026-08-04 13:45:59.257789+00', 'quote');
INSERT INTO public.notes VALUES ('59d41b08-b6ba-46ac-8b72-696bf7a92116', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'Or rather it is the same indivisible divinity active in us and in nature, and if the external world were destroyed, any one of us would be able to rebuild it, for mountain and river, tree and leaf, root and blossom, every form in nature has its model and prototype within us and arises from the soul whose essence is eternity, whose nature we do not know but which shows itself primarily as the power to love and the power to create.', NULL, '2026-07-28 06:08:43.019004+00', '2026-08-04 13:48:47.788283+00', 'quote');
INSERT INTO public.notes VALUES ('d54899a0-3b9f-4115-b9cc-fff8ff44b00e', 'acea4463-69fb-4b5f-8fa0-27450732d460', NULL, 'Emotions are the body’s response to the mind. When they come, don’t identify with it. Watch it come and go.', NULL, '2026-07-28 06:04:51.564214+00', '2026-07-28 06:04:51.564214+00', 'note');
INSERT INTO public.notes VALUES ('e4249011-67dd-4d8f-8cb3-2810f184bf5a', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, '“Stop!” Pistorius cried violently. “There is a very big difference between having the world inside you and knowing it!', NULL, '2026-08-04 13:51:52.654451+00', '2026-08-04 13:51:52.654451+00', 'quote');
INSERT INTO public.notes VALUES ('80233a82-a127-4831-af84-cdbb214ad364', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'Now every one of them contains the possibility of becoming human, but only when he intuits this possibility, or even learns to bring it at least partly into his consciousness, is it truly his.', NULL, '2026-08-04 13:53:11.123999+00', '2026-08-04 13:53:11.123999+00', 'quote');
INSERT INTO public.notes VALUES ('a7aa5b42-27d7-4e3d-af7f-73448724564a', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'Nothing that isn’t in us ever bothers us.', NULL, '2026-08-04 13:53:19.9413+00', '2026-08-04 13:53:19.9413+00', 'quote');
INSERT INTO public.notes VALUES ('ea245661-adc7-47ce-be5f-a8080a4a2d85', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'Most people live such unreal lives, because they see external images as reality and never give their own internal world a chance to express itself.', NULL, '2026-08-04 13:53:24.483582+00', '2026-08-04 13:53:24.483582+00', 'quote');
INSERT INTO public.notes VALUES ('deb742fa-9393-4499-8ccb-03e9e44c97a7', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'Maybe he was on a surer path in his drunkenness than I was in my timidity.', NULL, '2026-08-04 13:53:29.699092+00', '2026-08-04 13:53:29.699092+00', 'quote');
INSERT INTO public.notes VALUES ('a468367f-2cf4-45fc-a078-f06b1de18f51', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'Every person’s true calling was only to arrive at himself.', NULL, '2026-08-04 13:53:40.644482+00', '2026-08-04 13:53:40.644482+00', 'quote');
INSERT INTO public.notes VALUES ('4ac0b594-f842-4804-a02b-74a715096e9b', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'I was a roll of Nature’s dice, thrown into the unknown, maybe into a new world, maybe into the void, and my only purpose in life was to let this throw from the primal depths play out, feel its will inside me, and make that will entirely my own. Only that!', NULL, '2026-08-04 13:53:42.571816+00', '2026-08-04 13:53:42.571816+00', 'quote');
INSERT INTO public.notes VALUES ('f2ca5d6e-9873-4368-a57b-5716340a530c', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'They are afraid because they have never gotten to know who they really are.', NULL, '2026-08-04 13:53:57.807218+00', '2026-08-04 13:53:57.807218+00', 'quote');
INSERT INTO public.notes VALUES ('d9f1cc43-7be7-4ea2-b7ae-05bcc6bb96b2', '9fa8e5a3-a1c8-4d35-a20a-dd858d094190', NULL, 'We recognized only one thing as our duty and destiny: every one of us had to become himself, had to be true to and live for the sake of the seed of nature at work in himself, so completely that the uncertain future would find us ready for anything and everything it might bring.', NULL, '2026-08-04 13:54:04.770154+00', '2026-08-04 13:54:04.770154+00', 'quote');
INSERT INTO public.notes VALUES ('36d06a55-37b6-4af7-a261-63ed7027423e', '29385413-4327-42e7-be9b-fd14b56669ee', 'Never enough', 'Don’t compare yourself to anyone. Know when to stop. Your reputation matters more', NULL, '2026-08-04 13:59:58.337814+00', '2026-08-04 14:00:09.566092+00', 'note');
INSERT INTO public.notes VALUES ('f723bf61-5740-4ba9-b0cc-74f9f158131d', '29385413-4327-42e7-be9b-fd14b56669ee', 'Luck and risk', 'Nothing is as good or bad as it seems. Focus less on individuals and more on broad patterns. Bill Gates had a great advantage.', NULL, '2026-08-04 13:59:41.757171+00', '2026-08-04 14:00:21.406149+00', 'note');
INSERT INTO public.notes VALUES ('f48e97a2-2228-45fb-9b33-d60007891e8b', '29385413-4327-42e7-be9b-fd14b56669ee', 'No one’s crazy', 'We all make decisions based on our own unique experiences that seems to make sense to us in a given moment.', NULL, '2026-08-04 13:59:26.984607+00', '2026-08-04 14:00:42.501603+00', 'note');
INSERT INTO public.notes VALUES ('127d7cac-fae5-4412-a5df-d16305978d01', '29385413-4327-42e7-be9b-fd14b56669ee', 'Getting wealthy vs Staying wealthy', 'Good investing is not necessarily making good decisions. It’s about consistently not screwing up. Focus not on big returns but on being financially unbreakable.', NULL, '2026-08-04 14:01:21.350515+00', '2026-08-04 14:01:21.350515+00', 'note');
INSERT INTO public.notes VALUES ('78545090-9298-4ce0-bca0-de1be7190cd5', '29385413-4327-42e7-be9b-fd14b56669ee', 'Tails, you win', 'You can be wrong half the time and still make a fortune. Things will fail, you only need to get some of the best ones to win', NULL, '2026-08-04 14:02:01.29734+00', '2026-08-04 14:02:01.29734+00', 'note');
INSERT INTO public.notes VALUES ('2472cf52-7c3a-41c0-bf82-194a4e40e24d', '29385413-4327-42e7-be9b-fd14b56669ee', 'Freedom', 'Freedom is more important than chasing money. Freedom to do the things we want, with whom where etc.', NULL, '2026-08-04 14:02:17.752245+00', '2026-08-04 14:02:17.752245+00', 'note');
INSERT INTO public.notes VALUES ('885332ab-f093-406d-b40b-05378c565431', '29385413-4327-42e7-be9b-fd14b56669ee', 'Man in the car paradox', 'No one is impressed with your possessions as much as you are. When they see you with a supercar. They are not seeing you. They are imagining themselves in that car. You don’t get respect and admiration when you have nice things, it’s actually the material they admire, not you. Humility, kindness, and empathy will give you more respect than horsepower will ever will.', NULL, '2026-08-04 14:02:39.126029+00', '2026-08-04 14:02:39.126029+00', 'note');
INSERT INTO public.notes VALUES ('28db05ec-9fea-4ad0-a765-6ea04231eb87', '29385413-4327-42e7-be9b-fd14b56669ee', 'Wealth is what you don’t see', 'Spending money to show people how much money you have is the fastest way to have less money.', NULL, '2026-08-04 14:03:11.072194+00', '2026-08-04 14:03:11.072194+00', 'note');
INSERT INTO public.notes VALUES ('ced31883-93c7-45ff-a822-19fb06eb2b6d', '29385413-4327-42e7-be9b-fd14b56669ee', 'Save money', 'Save for saving’s sake, it gives you flexibility and time to think. Every bit of savings is like taking a point from the future that would owned by someone else and giving it back to yourself. In a world where intelligence is hyper-competitive, soft skills like communication, empathy, and flexibility are very important. Having more control over your time is becoming one of the most valuable currencies in the world.', NULL, '2026-08-04 14:03:44.556979+00', '2026-08-04 14:03:44.556979+00', 'note');
INSERT INTO public.notes VALUES ('f94e80d0-d99c-4115-95dc-7681553e11c6', '29385413-4327-42e7-be9b-fd14b56669ee', 'Reasonable > Rational', 'Be reasonalbe like a human than rational by solely depending on formulas.', NULL, '2026-08-04 14:03:57.197417+00', '2026-08-04 14:03:57.197417+00', 'note');
INSERT INTO public.notes VALUES ('5f1a0f4f-a8e2-4157-b608-058f4ab6185b', '29385413-4327-42e7-be9b-fd14b56669ee', 'Surprise!', 'Future is always unpredictable. Learning from history is not always beneficial as trend changes. But the general stuff matters everytime.', NULL, '2026-08-04 14:04:19.168487+00', '2026-08-04 14:04:19.168487+00', 'note');
INSERT INTO public.notes VALUES ('fd46a4b8-8ec8-4656-bf0e-bd63caffeb82', '29385413-4327-42e7-be9b-fd14b56669ee', 'Room for error', 'Always plan for errors happening. No risk is worth taking if it can break you fully. Keep savings to survive those situations, even if there is very less chance', NULL, '2026-08-04 14:04:34.734262+00', '2026-08-04 14:04:34.734262+00', 'note');
INSERT INTO public.notes VALUES ('a6c6384c-78df-4153-8f4c-47b69344ac57', '29385413-4327-42e7-be9b-fd14b56669ee', 'You’ll change', 'Avoid extreme ends of financial planning, accept the reality of changing our minds.', NULL, '2026-08-04 14:04:48.444884+00', '2026-08-04 14:04:48.444884+00', 'note');
INSERT INTO public.notes VALUES ('f708bef1-a19c-4a95-be70-be4136101948', '29385413-4327-42e7-be9b-fd14b56669ee', 'Nothing’s free', 'Everything has a price, not all appear on labels. Not see everything unnecessarily as fine.', NULL, '2026-08-04 14:05:06.325563+00', '2026-08-04 14:05:06.325563+00', 'note');
INSERT INTO public.notes VALUES ('6b073a70-1bdc-4f36-8509-2bbed09c0a43', '29385413-4327-42e7-be9b-fd14b56669ee', 'You & Me', 'Beware of taking financial cues from people playing a different game than you are.', NULL, '2026-08-04 14:05:20.845619+00', '2026-08-04 14:05:20.845619+00', 'note');
INSERT INTO public.notes VALUES ('092b64cc-9c65-440b-8ad1-cf9c6360d2c3', '29385413-4327-42e7-be9b-fd14b56669ee', 'The Seduction of Pessimism', 'Pessimism is more appreciated so don’t be deceived by it.', NULL, '2026-08-04 14:05:34.768204+00', '2026-08-04 14:05:34.768204+00', 'note');
INSERT INTO public.notes VALUES ('2e85ffe2-6873-4acf-b3c1-2afea4d8232d', '29385413-4327-42e7-be9b-fd14b56669ee', 'When You’ll Believe Anything', 'We see world and make assumptions based on our own knowledge and perspectives.', NULL, '2026-08-04 14:05:57.41954+00', '2026-08-04 14:05:57.41954+00', 'note');
INSERT INTO public.notes VALUES ('da1dcd58-6f37-4413-a62d-f8446de6952c', '5ef21e7f-3921-4655-8f59-ce68030d03b6', 'Atomic Habits Summary', '3 Key Lessons from Atomic Habits
This section of the Atomic Habits summary presents key points from three of the core themes of the book.
Lesson 1: Small habits make a big difference
It is so easy to overestimate the importance of one defining moment and underestimate the value of making small improvements on a daily basis.
Meanwhile, improving by 1 percent isn’t particularly notable— sometimes it isn’t even noticeable—but it can be far more meaningful, especially in the long run. The difference a tiny improvement can make over time is astounding. Here’s how the math works out: if you can get 1 percent better each day for one year, you’ll end up thirty-seven times better by the time you’re done. Conversely, if you get 1 percent worse each day for one year, you’ll decline nearly down to zero. What starts as a small win or a minor setback accumulates into something much more.
It doesn’t matter how successful or unsuccessful you are right now. What matters is whether your habits are putting you on the path toward success.
Focus on getting 1 percent better every day.
Lesson 2: Forget about setting goals. Focus on your system instead.
Goals are about the results you want to achieve. Systems are about the processes that lead to those results.
If you’re having trouble changing your habits, the problem isn’t you. The problem is your system. Bad habits repeat themselves again and again not because you don’t want to change, but because you have the wrong system for change.
You do not rise to the level of your goals. You fall to the level of your systems.
Atomic Habits presents a proven system for building good habits and breaking bad ones.
Lesson 3: Build identity-based habits
The key to building lasting habits is focusing on creating a new identity first. Your current behaviors are simply a reflection of your current identity. What you do now is a mirror image of the type of person you believe that you are (either consciously or subconsciously).
To change your behavior for good, you need to start believing new things about yourself. You need to build identity-based habits.
Changing your beliefs isn’t nearly as hard as you might think. There are two steps.
Decide the type of person you want to be.
Prove it to yourself with small wins.
Your identity emerges out of your habits. Every action is a vote for the type of person you wish to become.', NULL, '2026-08-07 10:17:39.294674+00', '2026-08-07 10:17:39.294674+00', 'note');
INSERT INTO public.notes VALUES ('37a05b3d-0b4b-4907-8043-2a52c974e05d', '5ef21e7f-3921-4655-8f59-ce68030d03b6', 'How to create a good habit', '- The 1st law (Cue): Make it obvious.
- The 2nd law (Craving): Make it attractive.
- The 3rd law (Response): Make it easy.
- The 4th law (Reward): Make it satisfying.', NULL, '2026-08-07 10:18:57.5906+00', '2026-08-07 10:18:57.5906+00', 'note');
INSERT INTO public.notes VALUES ('751537d0-216a-496f-bdc9-7fefa1d7a922', '5ef21e7f-3921-4655-8f59-ce68030d03b6', 'How to break a bad habit', 'Inversion of the 1st law (Cue): Make it invisible.
Inversion of the 2nd law (Craving): Make it unattractive.
Inversion of the 3rd law (Response): Make it difficult.
Inversion of the 4th law (Reward): Make it unsatisfying.', NULL, '2026-08-07 10:19:15.734659+00', '2026-08-07 10:19:15.734659+00', 'note');
INSERT INTO public.notes VALUES ('95026ee8-b8e6-4c20-9ea9-b837196462e6', '5ef21e7f-3921-4655-8f59-ce68030d03b6', NULL, '“Every action you take is a vote for the type of person you wish to become. No single instance will transform your beliefs, but as the votes build up, so does the evidence of your new identity. This is one reason why meaningful change does not require radical change. Small habits can make a meaningful difference by providing evidence of a new identity. And if a change is meaningful, it is actually big. That''s the paradox of making small improvements.”', NULL, '2026-08-07 10:19:39.270837+00', '2026-08-07 10:19:39.270837+00', 'quote');
INSERT INTO public.notes VALUES ('f21c4111-738a-4edb-88cc-7c05e4aad607', '5ef21e7f-3921-4655-8f59-ce68030d03b6', NULL, '“All big things come from small beginnings. The seed of every habit is a single, tiny decision. But as that decision is repeated, a habit sprouts and grows stronger. Roots entrench themselves and branches grow. The task of breaking a bad habit is like uprooting a powerful oak within us. And the task of building a good habit is like cultivating a delicate flower one day at a time.”', NULL, '2026-08-07 10:19:45.599068+00', '2026-08-07 10:19:45.599068+00', 'quote');
INSERT INTO public.notes VALUES ('8d331cd6-78df-4dc6-ab07-fdd982edf03e', '5ef21e7f-3921-4655-8f59-ce68030d03b6', NULL, '“The purpose of setting goals is to win the game. The purpose of building systems is to continue playing the game. True long-term thinking is goal-less thinking. It’s not about any single accomplishment. It is about the cycle of endless refinement and continuous improvement. Ultimately, it is your commitment to the process that will determine your progress.”', NULL, '2026-08-07 10:19:52.428706+00', '2026-08-07 10:19:52.428706+00', 'quote');


