INSERT INTO public.note_chunks VALUES ('b643c084-dc52-41a8-b498-ac8cf23ef468', 'da1dcd58-6f37-4413-a62d-f8446de6952c', 1, 'Conversely, if you get 1 percent worse each day for one year, you’ll decline nearly down to zero. What starts as a small win or a minor setback accumulates into something much more. It doesn’t matter how successful or unsuccessful you are right now. What matters is whether your habits are putting you on the path toward success. Focus on getting 1 percent better every day. Lesson 2: Forget about setting goals. Focus on your system instead. Goals are about the results you want to achieve. Systems are about the processes that lead to those results. If you’re having trouble changing your habits, the problem isn’t you. The problem is your system.', '[0.05727242,-0.0024774557,-0.01771063,0.018739006,-0.01491578,-0.01923161,0.010309556,0.08585561,-0.032514464,-0.059579752,0.012617858,0.0379209,0.07914826,0.030842207,0.06208374,-0.008685717,-0.04745179,0.0232827,-0.035252072,0.0141346585,-0.0530479,-0.0138843,-0.007156242,0.049101807,-0.05962193,0.040801577,-0.06783629,-0.047294248,-0.017161028,-0.07171766,0.01819542,-0.01457845,0.040055178,-0.046061758,-0.053874917,-0.01909574,0.0020019594,-0.02130377,-0.0067692664,0.03669181,0.035087377,0.030429153,-0.0010497227,-0.027019966,-0.027431585,-0.036719467,-0.0032475665,0.05685542,0.026611703,-0.002068066,-0.028360138,0.04346562,0.04591523,-4.5429177e-05,0.05935291,0.08706181,0.012426484,0.13077195,-0.026954938,-0.03973852,0.016349208,-0.009573644,-0.014984149,-0.037302043,0.048818994,0.016894823,-0.01555034,-0.010501668,-0.07047369,0.096011944,-0.09133023,-0.045508474,0.031112537,-0.022049008,0.07687967,0.05937678,-0.028830903,-0.035127074,0.069802105,0.07627169,0.03894598,0.032464676,-0.03291102,0.03325144,-0.024574133,-0.035555284,0.050376642,-0.0007594024,0.10780497,-0.04310459,0.006412121,0.016511524,0.055958137,-0.035324484,0.011152406,0.053754345,-0.03313636,-0.04873991,-0.04548213,0.026471842,-0.010