INSERT INTO public.note_chunks VALUES ('fc489e5b-1b37-4e61-942a-562925e0a3f1', 'da1dcd58-6f37-4413-a62d-f8446de6952c', 2, 'Bad habits repeat themselves again and again not because you don’t want to change, but because you have the wrong system for change. You do not rise to the level of your goals. You fall to the level of your systems. Atomic Habits presents a proven system for building good habits and breaking bad ones. Lesson 3: Build identity-based habits
